"""Filesystem predicates shared by the bfs command evaluator."""
import fnmatch
import grp
import os
import pwd
import re
import stat
import time


def bre_to_python(pattern):
    """Translate the common POSIX BRE operators to Python's regex syntax."""
    out = []
    in_class = False
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == "\\" and i + 1 < len(pattern):
            n = pattern[i + 1]
            if not in_class and n in "()|+?{}":
                out.append(n)
            else:
                out.append("\\" + n)
            i += 2
            continue
        if c == "[": in_class = True
        elif c == "]": in_class = False
        if not in_class and c in "()|+?{}": out.append("\\" + c)
        else: out.append(c)
        i += 1
    return "".join(out)


def number_match(value, spec):
    """find-style integer comparison: N exact, +N greater, -N less."""
    spec = str(spec)
    cmp = spec[:1] if spec[:1] in "+-" else ""
    n = int(spec[1:] if cmp else spec)
    return value > n if cmp == "+" else value < n if cmp == "-" else value == n


def _mode(path, follow):
    if not follow:
        return os.lstat(path)
    try:
        return os.stat(path, follow_symlinks=True)
    except OSError:
        # find still sees a dangling link under -L; it simply cannot follow it.
        return os.lstat(path)


def _type_match(st, types):
    m = st.st_mode
    table = {
        "b": stat.S_ISBLK(m), "c": stat.S_ISCHR(m), "d": stat.S_ISDIR(m),
        "p": stat.S_ISFIFO(m), "f": stat.S_ISREG(m), "l": stat.S_ISLNK(m),
        "s": stat.S_ISSOCK(m), "D": False,
    }
    return any(table.get(t, False) for t in types.replace(",", ""))


def _permission_match(mode, spec):
    # find's -perm octal modes; '-' means all requested bits, '/' means any.
    prefix = spec[:1] if spec[:1] in "-/" else ""
    value = spec[1:] if prefix else spec
    try:
        wanted = int(value, 8)
    except ValueError:
        try:
            wanted = 0
            file_mode = stat.S_IMODE(mode)
            actual = 0
            who_masks = {"u": 0o4700, "g": 0o2070, "o": 0o1007, "a": 0o7777}
            perm_masks = {"r": (0o400, 0o040, 0o004), "w": (0o200, 0o020, 0o002),
                          "x": (0o100, 0o010, 0o001)}
            for clause in value.split(","):
                i = 0; who = ""
                while i < len(clause) and clause[i] in "ugoa":
                    who += clause[i]; i += 1
                who = who or "a"
                if i >= len(clause) or clause[i] not in "+-=" or any(c not in who_masks for c in who):
                    return False
                op = clause[i]; i += 1
                bits = 0
                for c in clause[i:]:
                    if c in "rwx":
                        for person in who:
                            if person == "a": persons = "ugo"
                            else: persons = person
                            for p in persons:
